param([string]$RuntimeRoot=(Join-Path $env:LOCALAPPDATA "Executor"),[string]$OpenAITunnelCredentialsFile="",[string]$PublicHost="",[int]$PublicPort=9443,[string]$DeviceId="",[string]$ProfilePath=(Join-Path $PSScriptRoot "..\deploy\tunnel-client.executor.example.yaml"),[string]$TunnelClient="tunnel-client")
$ErrorActionPreference="Stop";$sp=Join-Path $RuntimeRoot "direct-state.json";if(Test-Path $sp){try{$s=Get-Content -Raw -Encoding UTF8 $sp|ConvertFrom-Json;if(-not$OpenAITunnelCredentialsFile){$OpenAITunnelCredentialsFile=[string]$s.credential_file};if(-not$PublicHost){$PublicHost=[string]$s.public_host};if($PublicPort-eq9443-and$s.public_port){$PublicPort=[int]$s.public_port}}catch{}};&(Join-Path $PSScriptRoot "Stop-ExecutorDirect.ps1") -RuntimeRoot $RuntimeRoot;&(Join-Path $PSScriptRoot "Start-ExecutorDirect.ps1") -RuntimeRoot $RuntimeRoot -OpenAITunnelCredentialsFile $OpenAITunnelCredentialsFile -PublicHost $PublicHost -PublicPort $PublicPort -DeviceId $DeviceId -ProfilePath $ProfilePath -TunnelClient $TunnelClient